CREATE TABLE schema_version_v8(version INTEGER PRIMARY KEY CHECK(version IN(1,2,3,4,5,6,7,8)),backend TEXT NOT NULL CHECK(backend='postgres'),checksum TEXT NOT NULL);
INSERT INTO schema_version_v8 SELECT * FROM schema_version;
DROP TABLE schema_version;
ALTER TABLE schema_version_v8 RENAME TO schema_version;
CREATE TABLE bonus_aggregate(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>=0),PRIMARY KEY(org_id,employee_id),UNIQUE(org_id,employee_id,revision),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id));
CREATE TABLE bonus_target(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','confirmed','withdrawn')),version_id TEXT NOT NULL,payload_id TEXT NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL CHECK(period_end>=period_start),actor_subject_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),basis_revision BIGINT NOT NULL CHECK(basis_revision>0),recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,revision),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,actor_subject_id) REFERENCES subject(org_id,id));
CREATE TABLE bonus_target_version(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,target_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','confirmed','withdrawn')),payload_id TEXT NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL CHECK(period_end>=period_start),actor_subject_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),basis_revision BIGINT NOT NULL CHECK(basis_revision>0),recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,target_id,revision),FOREIGN KEY(org_id,target_id,employee_id) REFERENCES bonus_target(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,actor_subject_id) REFERENCES subject(org_id,id));
CREATE TABLE bonus_award(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','submitted','approved','rejected','withdrawn')),version_id TEXT NOT NULL,payload_id TEXT NOT NULL,author_subject_id TEXT NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL CHECK(period_end>=period_start),target_id TEXT,corrects_award_id TEXT,approval_id TEXT,revision BIGINT NOT NULL CHECK(revision>0),basis_revision BIGINT NOT NULL CHECK(basis_revision>0),recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,revision),FOREIGN KEY(org_id,target_id,employee_id) REFERENCES bonus_target(org_id,id,employee_id),FOREIGN KEY(org_id,corrects_award_id,employee_id) REFERENCES bonus_award(org_id,id,employee_id),FOREIGN KEY(org_id,author_subject_id) REFERENCES subject(org_id,id));
CREATE TABLE bonus_award_revision(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,award_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','submitted','approved','rejected','withdrawn')),payload_id TEXT NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL CHECK(period_end>=period_start),target_id TEXT,corrects_award_id TEXT,actor_subject_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),basis_revision BIGINT NOT NULL CHECK(basis_revision>0),recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,award_id,revision),FOREIGN KEY(org_id,award_id,employee_id) REFERENCES bonus_award(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,actor_subject_id) REFERENCES subject(org_id,id));
CREATE TABLE bonus_approval(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,award_id TEXT NOT NULL,award_version_id TEXT NOT NULL,approver_subject_id TEXT NOT NULL,payload_id TEXT NOT NULL,award_revision BIGINT NOT NULL CHECK(award_revision>1),basis_revision BIGINT NOT NULL CHECK(basis_revision>=0),bonus_revision BIGINT NOT NULL CHECK(bonus_revision=basis_revision+1),recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,award_id),UNIQUE(org_id,award_version_id),FOREIGN KEY(org_id,award_id,employee_id) REFERENCES bonus_award(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,approver_subject_id) REFERENCES subject(org_id,id));
CREATE TABLE bonus_payment(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,payload_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('payment','reversal')),paid_date DATE NOT NULL,business_source TEXT NOT NULL CHECK(length(business_source) BETWEEN 1 AND 64 AND business_source~'^[a-z0-9_]+$'),award_id TEXT,original_payment_id TEXT,business_key_version BIGINT NOT NULL CHECK(business_key_version>0),basis_revision BIGINT NOT NULL CHECK(basis_revision>0),business_digest BYTEA NOT NULL CHECK(octet_length(business_digest)=32),recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),CHECK((kind='payment' AND original_payment_id IS NULL) OR (kind='reversal' AND original_payment_id IS NOT NULL)),FOREIGN KEY(org_id,award_id,employee_id) REFERENCES bonus_award(org_id,id,employee_id),FOREIGN KEY(org_id,original_payment_id,employee_id) REFERENCES bonus_payment(org_id,id,employee_id));
CREATE TABLE bonus_payment_business_index(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain='bonus_payment'),key_version BIGINT NOT NULL CHECK(key_version>0),digest BYTEA NOT NULL CHECK(octet_length(digest)=32),payment_id TEXT NOT NULL,PRIMARY KEY(org_id,employee_id,domain,key_version,digest),UNIQUE(org_id,payment_id),FOREIGN KEY(org_id,payment_id,employee_id) REFERENCES bonus_payment(org_id,id,employee_id));
CREATE TABLE bonus_payment_business_index_staging(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain='bonus_payment'),snapshot_id TEXT NOT NULL,key_version BIGINT NOT NULL CHECK(key_version>0),digest BYTEA NOT NULL CHECK(octet_length(digest)=32),payment_id TEXT NOT NULL,PRIMARY KEY(org_id,snapshot_id,payment_id),UNIQUE(org_id,employee_id,domain,snapshot_id,key_version,digest),FOREIGN KEY(org_id,payment_id,employee_id) REFERENCES bonus_payment(org_id,id,employee_id));
CREATE TABLE hmac_index_state(org_id TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain='bonus_payment'),active_version BIGINT NOT NULL CHECK(active_version>0),active_key_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('ready','migrating','blocked')),epoch BIGINT NOT NULL CHECK(epoch>0),snapshot_id TEXT,target_version BIGINT,target_key_id TEXT,checkpoint TEXT,manifest_digest BYTEA,CHECK((state='ready' AND snapshot_id IS NULL AND target_version IS NULL AND target_key_id IS NULL AND checkpoint IS NULL AND manifest_digest IS NULL) OR (state IN('migrating','blocked') AND snapshot_id IS NOT NULL AND target_version>0 AND target_key_id IS NOT NULL AND manifest_digest IS NOT NULL)),PRIMARY KEY(org_id,domain),FOREIGN KEY(org_id) REFERENCES organization(id));
INSERT INTO hmac_index_state(org_id,domain,active_version,active_key_id,state,epoch) SELECT id,'bonus_payment',1,'bonus-payment-v1','ready',1 FROM organization;
CREATE FUNCTION hmac_state_org_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO hmac_index_state(org_id,domain,active_version,active_key_id,state,epoch) VALUES(NEW.id,'bonus_payment',1,'bonus-payment-v1','ready',1); RETURN NEW; END $$;
CREATE TRIGGER hmac_state_org_insert AFTER INSERT ON organization FOR EACH ROW EXECUTE FUNCTION hmac_state_org_insert();
CREATE TABLE compensation_extension_version(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,payload_id TEXT NOT NULL,schema_type TEXT NOT NULL CHECK(schema_type='compensation_memo/v1'),schema_version INTEGER NOT NULL CHECK(schema_version=1),revision BIGINT NOT NULL CHECK(revision>0),basis_revision BIGINT NOT NULL CHECK(basis_revision>0),supersedes_id TEXT,recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,employee_id,schema_type,revision),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,supersedes_id,employee_id) REFERENCES compensation_extension_version(org_id,id,employee_id));
CREATE TABLE bonus_payload(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,record_id TEXT NOT NULL,version_id TEXT NOT NULL,object_kind TEXT NOT NULL CHECK(object_kind IN('bonus_target','bonus_award','bonus_decision','bonus_payment','compensation_extension')),purpose TEXT NOT NULL CHECK(purpose='financial'),schema_type TEXT NOT NULL CHECK(schema_type IN('bonus.target.v1','bonus.award.v1','bonus.decision.v1','bonus.payment.v1','compensation_memo/v1')),schema_version INTEGER NOT NULL CHECK(schema_version=1),format_version INTEGER NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL,kek_version BIGINT NOT NULL CHECK(kek_version>0),wrapped_dek BYTEA NOT NULL,sealed_bytes BYTEA NOT NULL CHECK(octet_length(sealed_bytes)>=28),created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,record_id,version_id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id));
CREATE TABLE bonus_command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-BONUS-02','OP-BONUS-03','OP-BONUS-04','OP-BONUS-05','OP-BONUS-06','OP-BONUS-07','OP-BONUS-08')),key TEXT NOT NULL,digest BYTEA NOT NULL CHECK(octet_length(digest)=32),result_json JSONB NOT NULL CHECK(jsonb_typeof(result_json)='object'),recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id));
CREATE TABLE bonus_hmac_maintenance_audit(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,approved_by_subject_id TEXT NOT NULL,request_id TEXT NOT NULL,target_version BIGINT NOT NULL CHECK(target_version>0),target_key_id TEXT NOT NULL CHECK(length(target_key_id) BETWEEN 1 AND 128),approval_digest BYTEA NOT NULL CHECK(octet_length(approval_digest)=32),actor_uid BIGINT NOT NULL CHECK(actor_uid BETWEEN 0 AND 4294967295),actor_host_hash BYTEA NOT NULL CHECK(octet_length(actor_host_hash)=32),recorded_at TIMESTAMPTZ NOT NULL,UNIQUE(org_id,request_id),FOREIGN KEY(org_id,approved_by_subject_id) REFERENCES subject(org_id,id));
ALTER TABLE capability_assignment DROP CONSTRAINT capability_assignment_capability_check;
ALTER TABLE capability_assignment ADD CONSTRAINT capability_assignment_capability_check CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','access_grant.manage','interview.read','interview.write','note.read','note.write','note.publish','action.read','action.write','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage'));
ALTER TABLE delegation_authority DROP CONSTRAINT delegation_authority_capability_check;
ALTER TABLE delegation_authority ADD CONSTRAINT delegation_authority_capability_check CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','interview.read','interview.write','note.read','note.write','note.publish','action.read','action.write','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage'));
ALTER TABLE access_grant DROP CONSTRAINT access_grant_capability_check;
ALTER TABLE access_grant ADD CONSTRAINT access_grant_capability_check CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','access_grant.manage','interview.read','interview.write','note.read','note.write','note.publish','action.read','action.write','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage'));
ALTER TABLE delegation_authority DROP CONSTRAINT delegation_authority_category_check;
ALTER TABLE delegation_authority ADD CONSTRAINT delegation_authority_category_check CHECK((((category='metadata' AND capability IN('organization.read','organization.write') AND purpose='organization_management') OR (category='pii' AND capability IN('pii.read','pii.write') AND purpose='organization_management') OR (category='audit' AND capability='access_grant.manage' AND purpose='security_administration') OR (purpose='interview_followup' AND ((category='metadata' AND capability IN('interview.read','interview.write','sensitive.export')) OR (category IN('shared','manager_private','hr_confidential') AND capability IN('note.read','note.write','note.publish','sensitive.export')) OR (category='shared' AND capability IN('action.read','action.write'))))) OR (category='financial' AND purpose='compensation_management' AND capability IN('compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','sensitive.export'))) AND capability<>'access_grant.manage');
ALTER TABLE access_grant DROP CONSTRAINT access_grant_category_check;
ALTER TABLE access_grant ADD CONSTRAINT access_grant_category_check CHECK((((category='metadata' AND capability IN('organization.read','organization.write') AND purpose='organization_management') OR (category='pii' AND capability IN('pii.read','pii.write') AND purpose='organization_management') OR (category='audit' AND capability='access_grant.manage' AND purpose='security_administration') OR (purpose='interview_followup' AND ((category='metadata' AND capability IN('interview.read','interview.write','sensitive.export')) OR (category IN('shared','manager_private','hr_confidential') AND capability IN('note.read','note.write','note.publish','sensitive.export')) OR (category='shared' AND capability IN('action.read','action.write'))))) OR (category='financial' AND purpose='compensation_management' AND capability IN('compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','sensitive.export'))));
ALTER TABLE access_grant ADD CONSTRAINT access_grant_bonus_employee_scope CHECK(capability NOT IN('bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage') OR object_kind IS NULL);
ALTER TABLE audit_event DROP CONSTRAINT audit_event_operation_check;
ALTER TABLE audit_event ADD CONSTRAINT audit_event_operation_check CHECK(operation IN('OP-ORG-01','OP-ORG-02','OP-ORG-03','OP-ORG-04','OP-ORG-05','OP-ORG-07','OP-ORG-06','OP-ORG-08','OP-SEC-01','OP-SEC-02','OP-SEC-03','OP-SEC-06','AUTH-LOGIN','AUTH-STEP-UP','AUTH-LOGOUT','AUTH-BIND','AUTH-UNBIND','OP-INT-01','OP-INT-02','OP-INT-03','OP-INT-04','OP-INT-05','OP-INT-06','OP-INT-07','OP-INT-08','OP-SEC-05','OP-COMP-01','OP-COMP-02','OP-COMP-03','OP-COMP-04','OP-COMP-05','OP-BONUS-01','OP-BONUS-02','OP-BONUS-03','OP-BONUS-04','OP-BONUS-05','OP-BONUS-06','OP-BONUS-07','OP-BONUS-08'));
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_action_check;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_action_check CHECK(action IN('','pii.write','access_grant.manage','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage'));
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_check2;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_check2 CHECK((mode='login' AND action='' AND expected_identity IS NULL) OR (mode='step_up' AND action IN('pii.write','access_grant.manage','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage') AND previous_hash IS NOT NULL AND expected_identity IS NOT NULL));
CREATE INDEX bonus_target_employee ON bonus_target(org_id,employee_id,period_start,id);
CREATE INDEX bonus_award_employee ON bonus_award(org_id,employee_id,period_start,id);
CREATE INDEX bonus_payment_employee ON bonus_payment(org_id,employee_id,paid_date,id);
CREATE INDEX bonus_payload_employee ON bonus_payload(org_id,employee_id);
CREATE FUNCTION bonus_fact_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable bonus fact' USING ERRCODE='23514'; END $$;
CREATE TRIGGER bonus_target_version_immutable BEFORE UPDATE OR DELETE ON bonus_target_version FOR EACH ROW EXECUTE FUNCTION bonus_fact_immutable();
CREATE TRIGGER bonus_award_revision_immutable BEFORE UPDATE OR DELETE ON bonus_award_revision FOR EACH ROW EXECUTE FUNCTION bonus_fact_immutable();
CREATE TRIGGER bonus_approval_immutable BEFORE UPDATE OR DELETE ON bonus_approval FOR EACH ROW EXECUTE FUNCTION bonus_fact_immutable();
CREATE TRIGGER bonus_payment_immutable BEFORE UPDATE OR DELETE ON bonus_payment FOR EACH ROW EXECUTE FUNCTION bonus_fact_immutable();
CREATE TRIGGER bonus_payload_immutable BEFORE UPDATE OR DELETE ON bonus_payload FOR EACH ROW EXECUTE FUNCTION bonus_fact_immutable();
CREATE TRIGGER compensation_extension_immutable BEFORE UPDATE OR DELETE ON compensation_extension_version FOR EACH ROW EXECUTE FUNCTION bonus_fact_immutable();
CREATE TRIGGER bonus_hmac_audit_immutable BEFORE UPDATE OR DELETE ON bonus_hmac_maintenance_audit FOR EACH ROW EXECUTE FUNCTION bonus_fact_immutable();
CREATE TRIGGER bonus_receipt_immutable BEFORE UPDATE OR DELETE ON bonus_command_receipt FOR EACH ROW EXECUTE FUNCTION bonus_fact_immutable();
